import test from 'node:test';
import assert from 'node:assert/strict';
import {selectRecords} from '../src/select.js';
const rows=[{id:'b',tenantId:'t1'},{id:'a',tenantId:'t1'},{id:'a',tenantId:'t2'}];
test('only selected current tenant',()=>assert.deepEqual(selectRecords(rows,'t1',['a']),[rows[1]]));
test('empty selection',()=>assert.deepEqual(selectRecords(rows,'t1',[]),[]));
test('order follows rows',()=>assert.deepEqual(selectRecords(rows,'t1',['a','b']),rows.slice(0,2)));
test('input unchanged',()=>{const input=structuredClone(rows),before=structuredClone(rows);selectRecords(input,'t1',['a']);assert.deepEqual(input,before);});
test('selected identifiers preserved',()=>{const ids=['b','a'];selectRecords(rows,'t1',ids);assert.deepEqual(ids,['b','a']);});

